#define MAX_GROUPS 3
regex_t compiled_pattern;
regmatch_t pmatch[MAX_GROUPS];
char *input = "User=admin,ID=9001";
char *pattern = "User=([a-z]+),ID=([0-9]+)";

// Compile the regex (POSIX requires REG_EXTENDED for modern syntax)
regcomp(&compiled_pattern, pattern, REG_EXTENDED);

// Execute the match
int status = regexec(&compiled_pattern, input,
                     MAX_GROUPS, pmatch, 0);

if (status == 0) {
    // Group 1: Username (Index 1)
    int user_start = pmatch[1].rm_so;
    int user_len = pmatch[1].rm_eo - user_start;

    // Group 2: ID (Index 2)
    int id_start = pmatch[2].rm_so;
    // The captured segment is input[user_start]...
}

regfree(&compiled_pattern);
